#!/usr/bin/env python3
"""Reproduce the SNTRUP761 and Poly1305 BC extractions and check upstream/local SHA-256 hashes."""

import argparse
import hashlib
import io
import json
from pathlib import Path
import re
import sys
import urllib.request
import zipfile

ROOT = Path(__file__).resolve().parents[2]
MANIFEST = ROOT / "third_party/bouncycastle/upstream.json"
OUTPUT = ROOT / "sshlib/src/main/java/org/connectbot/sshlib/crypto"
LICENSE = ROOT / "sshlib/src/main/resources/META-INF/LICENSE-bouncycastle.md"
PACKAGE = "org.connectbot.sshlib.crypto.sntrup"
PREFIX = "org/bouncycastle/"
NTRU = PREFIX + "pqc/crypto/ntruprime/"
CORE = [
    "SNTRUPrimeKEMExtractor", "SNTRUPrimeKeyGenerationParameters",
    "SNTRUPrimeKeyPairGenerator", "SNTRUPrimeKeyParameters", "SNTRUPrimeParameters",
    "SNTRUPrimePrivateKeyParameters", "SNTRUPrimePublicKeyParameters", "Utils",
]
SUPPORT = [
    "crypto/AsymmetricCipherKeyPair", "crypto/AsymmetricCipherKeyPairGenerator",
    "crypto/KeyGenerationParameters", "crypto/params/AsymmetricKeyParameter",
    "pqc/crypto/KEMParameters", "crypto/EncapsulatedSecretExtractor", "crypto/CipherParameters",
]
SNTRUP_FILES = [NTRU + n + ".java" for n in CORE] + [PREFIX + n + ".java" for n in SUPPORT]
POLY = "org/bouncycastle/crypto/macs/Poly1305.java"
PACK = "org/bouncycastle/util/Pack.java"
SOURCE_FILES = SNTRUP_FILES + [POLY, PACK]
LICENSE_ENTRY = "META-INF/LICENSE.md"
HEADER = """/*
 * Derived from Bouncy Castle; see META-INF/LICENSE-bouncycastle.md.
 * Generated by .github/scripts/vendor_bouncycastle.py. Do not edit directly.
 * Upstream provenance and SHA-256 hashes: third_party/bouncycastle/upstream.json.
 */

"""


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def read_archive(version):
    if not re.fullmatch(r"\d+(?:\.\d+)+", version):
        raise ValueError("Expected a numeric Maven release version")
    url = ("https://repo.maven.apache.org/maven2/org/bouncycastle/bcprov-jdk18on/"
           f"{version}/bcprov-jdk18on-{version}-sources.jar")
    with urllib.request.urlopen(url, timeout=60) as response:
        return response.read()


def client_utils(sources):
    """Keep the transitive method closure used by key generation/decapsulation."""
    source = sources[NTRU + "Utils.java"]
    methods = {}
    pattern = r"^    (?:(?:protected|private|public) )?static [^\n]+?\b(\w+)\([^\n]*\)\s*\n    \{"
    for match in re.finditer(pattern, source, re.M):
        if match[1] in methods:
            raise ValueError(f"Upstream Utils now overloads {match[1]}; review the extraction")
        start = source.index("{", match.start())
        depth, end = 1, start + 1
        while depth:
            depth += (source[end] == "{") - (source[end] == "}")
            end += 1
        methods[match[1]] = source[match.start():end] + "\n"
    roots = set(re.findall(r"Utils\.(\w+)\(", "\n".join(
        s for n, s in sources.items() if not n.endswith("/Utils.java"))))
    needed = set()

    def visit(name):
        if name in needed:
            return
        needed.add(name)
        for call in re.findall(r"\b(\w+)\(", methods[name]):
            if call in methods:
                visit(call)

    for name in roots:
        visit(name)
    # BC 1.87 batches random words and uses constants in its arithmetic helpers.
    # Retain referenced constant declarations verbatim alongside the method closure.
    bodies = "\n".join(methods[name] for name in needed)
    constants = [match[0] for match in re.finditer(
        r"^    (?:(?:protected|private|public) )?static final [^\n;]+?\b(\w+) = [^\n;]+;",
        source, re.M) if re.search(r"\b" + match[1] + r"\b", bodies)]
    if "getRandomUnsignedIntegers" in needed:
        methods["getRandomUnsignedIntegers"] = replace_once(
            methods["getRandomUnsignedIntegers"], "Pack.littleEndianToInt(bytes, 0, L);",
            "java.nio.ByteBuffer.wrap(bytes)"
            ".order(java.nio.ByteOrder.LITTLE_ENDIAN).asIntBuffer().get(L);")
    # Spell out Java's compound-assignment narrowing without changing the arithmetic.
    # Mask shifted operands to avoid sign extension. Final byte narrowing preserves
    # upstream's result modulo 256, including for coefficients outside -1, 0, 1.
    if "getEncodedSmallPolynomial" in needed:
        for shift in (2, 4, 6):
            original = f"x += (byte)(sp[spIndex++] + 1) << {shift};"
            explicit = f"x = (byte)(x + (((sp[spIndex++] + 1) & 0xff) << {shift}));"
            body = methods["getEncodedSmallPolynomial"]
            if body.count(original) != 1:
                raise ValueError("Upstream small-polynomial encoding changed; review the narrowing casts")
            methods["getEncodedSmallPolynomial"] = body.replace(original, explicit)
    # SHA-512 is mandatory on our Java/Android targets. Keep arithmetic unchanged.
    methods["getHashWithPrefix"] = """    protected static byte[] getHashWithPrefix(byte[] prefix, byte[] hashInput)
    {
        try
        {
            java.security.MessageDigest digest = java.security.MessageDigest.getInstance("SHA-512");
            digest.update(prefix);
            return digest.digest(hashInput);
        }
        catch (java.security.NoSuchAlgorithmException e)
        {
            throw new IllegalStateException(e);
        }
    }
"""
    return ("package org.bouncycastle.pqc.crypto.ntruprime;\n\n"
            "import java.security.SecureRandom;\n\nclass Utils\n{\n"
            + "\n".join(constants) + "\n"
            + "\n".join(body for name, body in methods.items() if name in needed) + "}\n")


def extract_sntrup(originals):
    sources = {n: data.decode("utf-8") for n, data in originals.items() if n.endswith(".java")}
    sources[NTRU + "Utils.java"] = client_utils(sources)
    generated = {}
    for name, source in sources.items():
        source = re.sub(r"package org\.bouncycastle[^;]*;", f"package {PACKAGE};", source)
        source = re.sub(r"import org\.bouncycastle[^;]*;\n", "", source)
        # Keep all Java types package-private: only the internal Kotlin adapter uses them.
        source = re.sub(r"^public (class|interface) ", r"\1 ", source, flags=re.M)
        source = source.replace("CryptoServicesRegistrar.getSecureRandom(random)",
                                "(random != null ? random : new SecureRandom())")
        source = source.replace("CryptoServicesRegistrar.getSecureRandom()", "new SecureRandom()")
        source = re.sub(r"Arrays.clone\((\w+)\)", r"\1.clone()", source)
        source = source.replace("Arrays.copyOfRange(", "java.util.Arrays.copyOfRange(")
        source = source.replace("Arrays.constantTimeAreEqual(", "java.security.MessageDigest.isEqual(")
        if name.endswith("/SNTRUPrimePrivateKeyParameters.java"):
            source = source.rstrip()[:-1] + """    // Local addition: erase retained private material after KEX or on failure.
    public void clear()
    {
        java.util.Arrays.fill(f, (byte)0);
        java.util.Arrays.fill(ginv, (byte)0);
        java.util.Arrays.fill(pk, (byte)0);
        java.util.Arrays.fill(rho, (byte)0);
        java.util.Arrays.fill(hash, (byte)0);
    }
}
"""
        if "CryptoServicesRegistrar" in source or "org.bouncycastle" in source:
            raise ValueError(f"Unadapted BC dependency in {name}")
        source = "\n".join(line.rstrip() for line in source.splitlines()).rstrip() + "\n"
        generated[name] = (HEADER + source).encode("utf-8")
    generated[LICENSE_ENTRY] = originals[LICENSE_ENTRY]
    return generated


def replace_once(source, old, new):
    if source.count(old) != 1:
        raise ValueError(f"Upstream structure changed; review extraction: {old[:80]}")
    return source.replace(old, new)


def method(source, signature):
    start = source.index(signature)
    end = source.index("\n    }", start) + len("\n    }")
    return source[start:end]


def extract_poly1305(originals):
    source = originals[POLY].decode()
    source = re.sub(r"package org\.bouncycastle\.crypto\.macs;", "package org.connectbot.sshlib.crypto;", source)
    source = re.sub(r"import org\.bouncycastle[^;]*;\n", "", source)
    source = replace_once(source, "public class Poly1305\n    implements Mac", "final class Poly1305Core")
    source = replace_once(source, "    private final BlockCipher cipher;\n", "")
    source = replace_once(source, "    private final byte[] singleByte = new byte[1];\n", "")
    source = replace_once(source, " * @see Poly1305KeyGenerator\n", "")
    start = source.index("    /**\n     * Constructs a Poly1305 MAC")
    end = source.index("    private void setKey", start)
    source = source[:start] + """    public void init(byte[] key)
    {
        setKey(key);
        reset();
    }

""" + source[end:]
    source = replace_once(source, "private void setKey(final byte[] key, final byte[] nonce)", "private void setKey(final byte[] key)")
    start = source.index("        if (cipher != null")
    end = source.index("        // Extract r portion", start)
    source = source[:start] + source[end:]
    start = source.index("        final byte[] kBytes;")
    end = source.index("        k0 = Pack.littleEndianToInt", start)
    source = source[:start] + "        final byte[] kBytes = key;\n        final int kOff = BLOCK_SIZE;\n\n" + source[end:]
    start = source.index("    public String getAlgorithmName()")
    end = source.index("    public void update(final byte[]", start)
    source = source[:start] + source[end:]
    source = source.replace("        throws DataLengthException,\n        IllegalStateException\n", "")
    source = replace_once(source, 'new OutputLengthException("Output buffer is too short.")', 'new IllegalArgumentException("Output buffer is too short.")')
    source = source.replace("Pack.", "Poly1305Pack.")
    # Each masked input is at most 26 bits (25 for h4 including hibit), so narrowing it is exact.
    # Keep BC's int accumulator addition, including its Java overflow semantics.
    inputs = [
        "t0 & 0x3ffffff",
        "(((t1 << 32) | t0) >>> 26) & 0x3ffffff",
        "(((t2 << 32) | t1) >>> 20) & 0x3ffffff",
        "(((t3 << 32) | t2) >>> 14) & 0x3ffffff",
        "(t3 >>> 8) + hibit",
    ]
    for limb, expression in enumerate(inputs):
        source = replace_once(source, f"h{limb} += {expression};",
                              f"h{limb} += (int)({expression});")

    # Local lifecycle addition: BC reset retains the key; SSH discards each one-time key.
    source = source.rstrip()[:-1] + """    public void clear()
    {
        reset();
        r0 = r1 = r2 = r3 = r4 = 0;
        s1 = s2 = s3 = s4 = 0;
        k0 = k1 = k2 = k3 = 0;
        java.util.Arrays.fill(currentBlock, (byte)0);
    }
}
"""
    pack = originals[PACK].decode()
    pack = ("package org.connectbot.sshlib.crypto;\n\nfinal class Poly1305Pack\n{\n"
            + method(pack, "    public static int littleEndianToInt(byte[] bs, int off)") + "\n\n"
            + method(pack, "    public static void intToLittleEndian(int n, byte[] bs, int off)") + "\n}\n")
    if "org.bouncycastle" in source or "cipher." in source or "BlockCipher" in source:
        raise ValueError("Unadapted BC dependency")
    def encode(text):
        return (HEADER + "\n".join(line.rstrip() for line in text.splitlines()).rstrip() + "\n").encode()
    return {POLY: encode(source), PACK: encode(pack), LICENSE_ENTRY: originals[LICENSE_ENTRY]}



def extract(originals):
    sntrup = {name: data for name, data in originals.items() if name not in (POLY, PACK)}
    generated = extract_sntrup(sntrup)
    if POLY in originals or PACK in originals:
        generated.update(extract_poly1305(originals))
    return generated


def destination(name, output=OUTPUT, license_file=LICENSE):
    if name == LICENSE_ENTRY:
        return license_file
    if name == POLY:
        return output / "Poly1305Core.java"
    if name == PACK:
        return output / "Poly1305Pack.java"
    return output / "sntrup" / name.rsplit("/", 1)[1]


def verify(manifest, originals, generated, output=OUTPUT, license_file=LICENSE):
    errors = []
    if set(manifest["files"]) != set(originals):
        errors.append("Upstream file inventory differs from the recorded manifest")
    for name, original in originals.items():
        recorded = manifest["files"].get(name, {})
        if recorded.get("originalSha256") != sha256(original):
            errors.append(f"UPSTREAM CHANGED: {name}\n  recorded: {recorded.get('originalSha256')}\n  released: {sha256(original)}")
        expected = generated[name]
        if recorded.get("extractedSha256") != sha256(expected):
            errors.append(f"EXTRACTION CHANGED: {name}\n  recorded: {recorded.get('extractedSha256')}\n  regenerated: {sha256(expected)}")
        path = destination(name, output, license_file)
        if not path.exists() or path.read_bytes() != expected:
            errors.append(f"VENDORED FILE DIFFERS: {path}")
    unexpected = {p.relative_to(output).as_posix() for p in output.rglob("*.java")} - {
        destination(n, output, license_file).relative_to(output).as_posix()
        for n in generated if n.endswith(".java")}
    if unexpected:
        errors.append(f"Unexpected vendored Java files: {sorted(unexpected)}")
    return errors


def main():
    parser = argparse.ArgumentParser(description=__doc__, allow_abbrev=False)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="verify without modifying files (default)")
    mode.add_argument("--update", action="store_true", help="regenerate sources and accept hashes for review")
    parser.add_argument("--archive-stdin", action="store_true", help="read a BC sources JAR from stdin instead of downloading")
    args = parser.parse_args()
    manifest = json.loads(MANIFEST.read_text())
    if manifest["artifact"] != "org.bouncycastle:bcprov-jdk18on":
        raise ValueError("Unexpected upstream artifact")
    archive_bytes = sys.stdin.buffer.read() if args.archive_stdin else read_archive(manifest["version"])
    with zipfile.ZipFile(io.BytesIO(archive_bytes)) as archive:
        originals = {name: archive.read(name) for name in SOURCE_FILES + [LICENSE_ENTRY]}
    generated = extract(originals)
    if args.update:
        for name, data in generated.items():
            path = destination(name)
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(data)
        manifest["reviewedVersion"] = manifest["version"]
        manifest["files"] = {name: {"originalSha256": sha256(data), "extractedSha256": sha256(generated[name])}
                             for name, data in originals.items()}
        MANIFEST.write_text(json.dumps(manifest, indent=2) + "\n")
        print("Regenerated Bouncy Castle sources and hashes. Review all changes before committing.")
        return 0
    errors = verify(manifest, originals, generated)
    if errors:
        print("\n".join(errors), file=sys.stderr)
        print("Review upstream against reviewedVersion, then run --update and the crypto tests.", file=sys.stderr)
        return 1
    print(f"BC {manifest['version']}: all {len(originals)} upstream and extracted SHA-256 hashes match.")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (OSError, ValueError, KeyError, zipfile.BadZipFile) as error:
        sys.exit(f"Bouncy Castle source verification failed: {error}")
